import React, { useState, useEffect, useRef } from "react";
import { supabase } from "./supabase";

/* ============================================================================
   JUVENTUDE 40 GRAUS — redesign seguindo o design system oficial
   Areia = base · laranja = ação · tinta = texto · sol = 1 raio (sem sunburst)
============================================================================ */

const LOGO_BANNER = "data:image/jpeg;base64,";

// ---- Tokens ----
const T = {
  paper: "#FCF4E6", paper2: "#FFFBF2", line: "#EADFC9",
  ink: "#2A1A10", inkSoft: "#6E5A4C", inkMute: "#A2907E",
  orange: "#EF5B25", orangeDeep: "#C4341A", gold: "#F5A623", goldSoft: "#F7C24B", red: "#D63426",
  gradHeat: "linear-gradient(90deg,#FCE1B0,#F5A623,#EF5B25,#C42D1B)",
  gradHero: "linear-gradient(150deg,#F5A623 0%,#EF5B25 52%,#C4341A 100%)",
  gradCta: "linear-gradient(135deg,#F7C24B,#F5A623)",
  shadow: "0 18px 40px -22px rgba(66,30,10,.45)",
  shadowSoft: "0 8px 22px -14px rgba(66,30,10,.35)",
};

const TEMAS = ["Educação", "Trabalho e Renda", "Cultura e Esporte", "Saúde e Saúde Mental", "Meio Ambiente", "Segurança e Direitos", "Mobilidade e Cidade", "Participação e Juventude", "Outro"];
const TEMA_COR = {
  "Educação": "#E23A2E", "Trabalho e Renda": "#EF7B23", "Cultura e Esporte": "#C0397E",
  "Saúde e Saúde Mental": "#1E9E6A", "Meio Ambiente": "#159A57", "Segurança e Direitos": "#6A3AD1",
  "Mobilidade e Cidade": "#2C6FE0", "Participação e Juventude": "#D98A00", "Outro": "#8A7360",
};
const tint = (hex, aa) => hex + aa; // hex + alpha hex (ex "1F")

// Senha/login: agora via Supabase Auth (e-mail + senha).
const SYSTEM_CHAT = `Você é o "Sol", agente da Juventude 40 Graus (juventude do Ceará, ciclo 2026). Ajuda o jovem a transformar o que vive numa proposta concreta de política pública.
Regras:
- Português do Brasil, tom jovem, caloroso, nordestino. Frases curtas.
- Comece descobrindo o que mais incomoda a pessoa na cidade dela. NÃO pergunte nome nem cidade — isso é preenchido no fim, ao enviar.
- Uma pergunta por vez. Descubra: problema, quem é afetado, e o que fazer na prática.
- Fique no tema (juventude/cidade/Ceará). Fora do escopo, recuse com leveza e traga de volta.
- Não prometa nada em nome de candidato nem faça propaganda. A ideia é da pessoa.
- Não peça dados sensíveis. Quando a ideia estiver redonda, incentive tocar em "Enviar minha proposta".`;
const SYSTEM_EXTRACT = `Extraia UMA proposta da conversa. Responda APENAS JSON válido (sem markdown):
{"titulo":"curto e chamativo","tema":"um de: ${TEMAS.join(" | ")}","problema":"1-2 frases","proposta":"1-3 frases","beneficiarios":"curto","nome":"primeiro nome se aparecer","cidade":"cidade se aparecer","idade":"faixa etária (16–17, 18–24, 25–29 ou 30–35) se der pra inferir, senão vazio"}
Campos ausentes = string vazia. Nunca invente nome ou cidade.`;

// ---- Agente de IA via nosso servidor (Gemini, chave protegida) ----
async function callAgent(messages, system) {
  const res = await fetch("/api/chat", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ system, messages }),
  });
  if (!res.ok) throw new Error("api");
  const data = await res.json();
  return (data.text || "").trim();
}

// ---- Dados no Supabase ----
async function listMural() {
  const { data, error } = await supabase.from("mural").select("*").order("curtidas", { ascending: false }).order("criado_em", { ascending: false });
  if (error) return [];
  return data || [];
}
async function listDossie() {
  const { data, error } = await supabase.from("ideias").select("*").eq("aprovada", true).order("criado_em", { ascending: false });
  if (error) return [];
  return data || [];
}
async function listPendentes() {
  const { data, error } = await supabase.from("ideias").select("*").eq("aprovada", false).order("criado_em", { ascending: false });
  if (error) return [];
  return data || [];
}
async function aprovarIdeia(id) { await supabase.from("ideias").update({ aprovada: true }).eq("id", id); }
async function recusarIdeia(id) { await supabase.from("ideias").delete().eq("id", id); }
async function saveIdeia(idea) {
  const { error } = await supabase.from("ideias").insert(idea);
  if (error) throw error;
  return true;
}
async function curtirIdeia(id) {
  try { await supabase.rpc("curtir", { ideia_id: id }); } catch (e) {}
}

// ---- Ícones ----
function SunMark({ size = 30, color }) {
  const c = color || T.gold;
  const rays = Array.from({ length: 8 });
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" aria-hidden="true">
      {rays.map((_, i) => {
        const a = (i * 45 * Math.PI) / 180;
        return <line key={i} x1={24 + Math.cos(a) * 15} y1={24 + Math.sin(a) * 15} x2={24 + Math.cos(a) * 21} y2={24 + Math.sin(a) * 21} stroke={c} strokeWidth="3" strokeLinecap="round" />;
      })}
      <circle cx="24" cy="24" r="11" fill={c} />
    </svg>
  );
}
function Icon({ name, size = 22, color, fill }) {
  const s = { width: size, height: size, fill: fill || "none", stroke: color, strokeWidth: 2, strokeLinecap: "round", strokeLinejoin: "round" };
  if (name === "chat") return <svg viewBox="0 0 24 24" {...s}><path d="M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z" /></svg>;
  if (name === "fire") return <svg viewBox="0 0 24 24" {...s}><path d="M12 3s5 4 5 9a5 5 0 0 1-10 0c0-2 1-3 1-3s0 2 2 2c1.5 0 1-3-1-5 2 0 3-2 3-5z" /></svg>;
  if (name === "lock") return <svg viewBox="0 0 24 24" {...s}><rect x="5" y="11" width="14" height="9" rx="2" /><path d="M8 11V8a4 4 0 0 1 8 0v3" /></svg>;
  if (name === "pin") return <svg viewBox="0 0 24 24" {...s}><path d="M12 21s7-6 7-11a7 7 0 1 0-14 0c0 5 7 11 7 11z" /><circle cx="12" cy="10" r="2.5" /></svg>;
  if (name === "menu") return <svg viewBox="0 0 24 24" {...s}><path d="M4 7h16M4 12h16M4 17h16" /></svg>;
  if (name === "x") return <svg viewBox="0 0 24 24" {...s}><path d="M6 6l12 12M18 6L6 18" /></svg>;
  if (name === "back") return <svg viewBox="0 0 24 24" {...s}><path d="M15 6l-6 6 6 6" /></svg>;
  return null;
}

// ---- Componentes base ----
function ThemeChip({ tema, active, onClick, small }) {
  const cor = TEMA_COR[tema] || T.orange;
  return (
    <button onClick={onClick} style={{
      display: "inline-flex", alignItems: "center", gap: 7, flexShrink: 0,
      border: active ? `2px solid ${cor}` : `1.5px solid ${T.line}`,
      background: active ? tint(cor, "1A") : T.paper2, color: T.ink,
      borderRadius: 999, padding: small ? "5px 11px" : "7px 13px", fontSize: small ? 12.5 : 13.5, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap",
    }}>
      <span style={{ width: 8, height: 8, borderRadius: 999, background: cor }} />{tema}
    </button>
  );
}
function FilterPill({ label, active, onClick }) {
  return (
    <button onClick={onClick} style={{
      flexShrink: 0, border: `1.5px solid ${active ? T.ink : T.line}`, background: active ? T.ink : "transparent",
      color: active ? "#fff" : T.inkSoft, borderRadius: 999, padding: "6px 13px", fontSize: 13, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap",
    }}>{label}</button>
  );
}
function Bubble({ role, children }) {
  const me = role === "user";
  return (
    <div style={{ display: "flex", justifyContent: me ? "flex-end" : "flex-start", marginBottom: 12, gap: 8 }}>
      {!me && <div style={{ flexShrink: 0, alignSelf: "flex-end", width: 30, height: 30, borderRadius: 999, background: T.gradCta, display: "flex", alignItems: "center", justifyContent: "center" }}><SunMark size={18} color="#fff" /></div>}
      <div style={{
        maxWidth: "80%", padding: "11px 14px", borderRadius: 18,
        borderBottomLeftRadius: me ? 18 : 5, borderBottomRightRadius: me ? 5 : 18,
        background: me ? T.gradCta : T.paper2, color: me ? "#fff" : T.ink,
        border: me ? "none" : `1.5px solid ${T.line}`, fontSize: 15, lineHeight: 1.45, whiteSpace: "pre-wrap", wordBreak: "break-word",
      }}>{children}</div>
    </div>
  );
}

// contador animado (para o termômetro)
function useCountUp(target, run) {
  const [v, setV] = useState(0);
  useEffect(() => {
    if (!run) { setV(target); return; }
    let raf, t0;
    const dur = 1300;
    const step = (t) => { if (!t0) t0 = t; const p = Math.min(1, (t - t0) / dur); const e = 1 - Math.pow(1 - p, 3); setV(target * e); if (p < 1) raf = requestAnimationFrame(step); };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, run]);
  return v;
}

// ---- Termômetro radial (assinatura do Mural) ----
function Gauge({ temp, run }) {
  const shown = useCountUp(temp, run);
  const R = 82, CX = 100, CY = 96, L = Math.PI * R;
  const frac = Math.max(0, Math.min(1, (temp - 34) / 6)); // meta 40°
  const quente = temp >= 40;
  return (
    <div style={{ position: "relative", width: 200, margin: "0 auto" }}>
      <svg width="200" height="112" viewBox="0 0 200 112">
        <defs>
          <linearGradient id="heat" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor="#FCE1B0" /><stop offset=".45" stopColor="#F5A623" /><stop offset=".75" stopColor="#EF5B25" /><stop offset="1" stopColor="#C42D1B" />
          </linearGradient>
        </defs>
        <path d={`M${CX - R},${CY} A${R},${R} 0 0 1 ${CX + R},${CY}`} fill="none" stroke={T.line} strokeWidth="13" strokeLinecap="round" />
        <path d={`M${CX - R},${CY} A${R},${R} 0 0 1 ${CX + R},${CY}`} fill="none" stroke="url(#heat)" strokeWidth="13" strokeLinecap="round" strokeDasharray={`${frac * L} ${L}`} style={{ transition: "stroke-dasharray .6s" }} />
      </svg>
      <div style={{ position: "absolute", inset: 0, top: 34, textAlign: "center" }}>
        <div className="disp tnum" style={{ fontSize: 46, lineHeight: 1, color: T.orangeDeep }}>{shown.toFixed(1)}°{quente ? "" : ""}</div>
        <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", color: T.inkMute, marginTop: 2 }}>meta 40°{quente ? " • fervendo 🔥" : ""}</div>
      </div>
    </div>
  );
}

// ---- Toast ----
function Toast({ msg }) {
  if (!msg) return null;
  return <div className="toast" style={{ position: "fixed", left: "50%", bottom: 84, transform: "translateX(-50%)", background: T.ink, color: "#fff", padding: "10px 18px", borderRadius: 999, fontSize: 13.5, fontWeight: 600, zIndex: 60, boxShadow: T.shadow }}>{msg}</div>;
}

// ============================ APP ============================
export default function App() {
  const [tab, setTab] = useState("conversar");
  const [ideias, setIdeias] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [session, setSession] = useState(null);
  const [toast, setToast] = useState("");
  const [consentiu, setConsentiu] = useState(() => { try { return localStorage.getItem("consentiu40") === "1"; } catch { return true; } });
  const [menu, setMenu] = useState(false);
  const [coordAberta, setCoordAberta] = useState(false);

  const [msgs, setMsgs] = useState([{ role: "assistant", content: "Salve! Eu sou o Sol ☀️, agente da Juventude 40 Graus. Se você pudesse mudar UMA coisa pra galera jovem da sua cidade, o que seria?" }]);
  const [input, setInput] = useState("");
  const [pensando, setPensando] = useState(false);
  const [rascunho, setRascunho] = useState(null);
  const [extraindo, setExtraindo] = useState(false);
  const [sucesso, setSucesso] = useState(null); // {delta}
  const scrollRef = useRef(null);

  const showToast = (m) => { setToast(m); setTimeout(() => setToast(""), 1700); };

  useEffect(() => {
    (async () => { setIdeias(await listMural()); setCarregando(false); })();
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));
    return () => sub.subscription.unsubscribe();
  }, []);
  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [msgs, pensando]);

  const iniciou = msgs.some((m) => m.role === "user");

  async function enviarTexto(texto) {
    const t = (texto || "").trim();
    if (!t || pensando) return;
    const novo = [...msgs, { role: "user", content: t }];
    setMsgs(novo); setInput(""); setPensando(true);
    try {
      const r = await callAgent(novo.map((m) => ({ role: m.role, content: m.content })), SYSTEM_CHAT);
      setMsgs([...novo, { role: "assistant", content: r || "Bora, me conta mais!" }]);
    } catch {
      setMsgs([...novo, { role: "assistant", content: "Muita gente falando comigo agora 🔥 — tenta de novo em 1 minutinho, ou já toca em Enviar minha proposta." }]);
    } finally { setPensando(false); }
  }
  async function iniciarEnvio() {
    setExtraindo(true); setRascunho(null);
    let draft = { titulo: "", tema: "Outro", problema: "", proposta: "", beneficiarios: "", nome: "", cidade: "", idade: "" };
    try {
      const conversa = msgs.map((m) => (m.role === "user" ? "JOVEM: " : "SOL: ") + m.content).join("\n");
      const out = await callAgent([{ role: "user", content: conversa }], SYSTEM_EXTRACT);
      const parsed = JSON.parse(out.replace(/```json/gi, "").replace(/```/g, "").trim());
      draft = { ...draft, ...parsed };
      if (!TEMAS.includes(draft.tema)) draft.tema = "Outro";
    } catch (e) {}
    setRascunho(draft); setExtraindo(false);
  }
  async function confirmarEnvio() {
    await saveIdeia(rascunho);
    setRascunho(null);
    setSucesso(true);
  }

  if (!consentiu) return <ConsentGate onAceitar={() => { try { localStorage.setItem("consentiu40", "1"); } catch (e) {} setConsentiu(true); }} />;

  return (
    <div style={{ minHeight: "100vh", background: T.orangeDeep, display: "flex", justifyContent: "center", fontFamily: "'Archivo',system-ui,sans-serif", color: T.ink }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700;12..96,800&family=Archivo:wght@400;500;600;700&display=swap');
        *{ box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
        .disp{ font-family:'Bricolage Grotesque','Archivo',system-ui,sans-serif; font-weight:800; letter-spacing:-.01em; }
        .tnum{ font-feature-settings:"tnum"; font-variant-numeric:tabular-nums; }
        .eyebrow{ font-size:11px; font-weight:700; letter-spacing:.16em; text-transform:uppercase; }
        button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{ outline:2px solid ${T.orange}; outline-offset:2px; }
        .scroll::-webkit-scrollbar{ width:7px; } .scroll::-webkit-scrollbar-thumb{ background:${T.line}; border-radius:8px; }
        @keyframes rise{ from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} } .rise{ animation:rise .3s ease both; }
        @keyframes toastin{ from{opacity:0;transform:translate(-50%,10px)} to{opacity:1;transform:translate(-50%,0)} } .toast{ animation:toastin .2s ease; }
        @keyframes pop{ 0%{transform:scale(.7);opacity:.4} 60%{transform:scale(1.12)} 100%{transform:scale(1);opacity:1} } .pop{ animation:pop .5s ease; }
        @media (prefers-reduced-motion: reduce){ .rise,.toast,.pop{ animation:none !important; } }
        input::placeholder,textarea::placeholder{ color:${T.inkMute}; }
      `}</style>

      <div style={{ width: "100%", maxWidth: 460, height: "100vh", overflow: "hidden", background: T.paper, display: "flex", flexDirection: "column", position: "relative", boxShadow: "0 0 40px rgba(0,0,0,.22)" }}>
        {/* Header */}
        <header style={{ flexShrink: 0, display: "flex", alignItems: "center", gap: 10, padding: "11px 16px", background: T.paper, borderBottom: `1px solid ${T.line}`, zIndex: 15 }}>
          <div className="disp" style={{ fontSize: 21, color: T.ink, lineHeight: 1 }}>Juventude <span style={{ color: T.orange }}>40°</span></div>
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 8 }}>
            <SunMark size={26} />
            <button onClick={() => setMenu(true)} aria-label="Menu" style={{ width: 38, height: 38, borderRadius: 12, border: `1px solid ${T.line}`, background: T.paper2, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><Icon name="menu" size={22} color={T.ink} /></button>
          </div>
        </header>

        {/* Conteúdo */}
        <main className="scroll" style={{ flex: 1, overflowY: "auto", display: "flex", flexDirection: "column", minHeight: 0 }}>
          {tab === "conversar" && (
            <ConversarView msgs={msgs} iniciou={iniciou} pensando={pensando} extraindo={extraindo} input={input} setInput={setInput}
              scrollRef={scrollRef} onEnviar={() => enviarTexto(input)} onSend={enviarTexto}
              onQuick={(tema) => enviarTexto(`Quero falar sobre ${tema.toLowerCase()} na minha cidade.`)} onProposta={iniciarEnvio} participantes={ideias.length} />
          )}
          {tab === "mural" && <MuralView ideias={ideias} carregando={carregando} onCurtir={curtirIdeia} onToast={showToast} />}
        </main>

        {/* Barra fixa (estilo pílula, laranja) */}
        <div style={{ flexShrink: 0, background: T.paper, padding: "9px 14px calc(12px + env(safe-area-inset-bottom))", borderTop: `1px solid ${T.line}` }}>
          <nav style={{ display: "flex", gap: 6, background: T.paper2, border: `1px solid ${T.line}`, borderRadius: 999, padding: 6, boxShadow: T.shadowSoft }}>
            {[["conversar", "Conversar", "chat"], ["mural", "Mural", "fire"]].map(([k, label, ic]) => {
              const on = tab === k;
              return (
                <button key={k} onClick={() => setTab(k)} style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, padding: "12px 0", borderRadius: 999, border: "none", cursor: "pointer", background: on ? T.orange : "transparent", color: on ? "#fff" : T.inkMute, transition: "background .15s" }}>
                  <Icon name={ic} size={21} color={on ? "#fff" : T.inkMute} fill={on ? "#fff" : "none"} />
                  <span style={{ fontSize: 14.5, fontWeight: on ? 800 : 600 }}>{label}</span>
                </button>
              );
            })}
          </nav>
        </div>

        {/* Menu lateral */}
        {menu && <div onClick={() => setMenu(false)} style={{ position: "absolute", inset: 0, background: "rgba(42,26,16,.45)", zIndex: 30 }} />}
        <div style={{ position: "absolute", top: 0, bottom: 0, left: 0, width: "76%", maxWidth: 300, background: T.paper, zIndex: 31, boxShadow: T.shadow, transform: menu ? "translateX(0)" : "translateX(-105%)", transition: "transform .25s ease", padding: 18, display: "flex", flexDirection: "column" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <div className="disp" style={{ fontSize: 20 }}>Menu</div>
            <button onClick={() => setMenu(false)} aria-label="Fechar" style={{ width: 34, height: 34, borderRadius: 10, border: `1px solid ${T.line}`, background: T.paper2, cursor: "pointer" }}><Icon name="x" size={18} color={T.ink} /></button>
          </div>
          <button onClick={() => { setMenu(false); setCoordAberta(true); }} style={{ marginTop: 18, display: "flex", alignItems: "center", gap: 12, padding: 14, borderRadius: 14, border: `1px solid ${T.line}`, background: T.paper2, cursor: "pointer", textAlign: "left" }}>
            <div style={{ width: 38, height: 38, borderRadius: 999, background: T.gradCta, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Icon name="lock" size={20} color="#fff" /></div>
            <div><div style={{ fontWeight: 800, fontSize: 15, color: T.ink }}>Área da coordenação</div><div style={{ fontSize: 12, color: T.inkMute }}>Login · dossiê e moderação</div></div>
          </button>
          <div style={{ marginTop: "auto", fontSize: 11.5, color: T.inkMute, lineHeight: 1.5 }}>Só a coordenação usa esta parte. O público vê apenas Conversar e Mural.</div>
        </div>

        {/* Área da coordenação (sobreposta) */}
        {coordAberta && (
          <div style={{ position: "absolute", inset: 0, background: T.paper, zIndex: 40, display: "flex", flexDirection: "column" }}>
            <div style={{ flexShrink: 0, display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderBottom: `1px solid ${T.line}` }}>
              <button onClick={() => setCoordAberta(false)} aria-label="Voltar" style={{ width: 36, height: 36, borderRadius: 10, border: `1px solid ${T.line}`, background: T.paper2, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><Icon name="back" size={18} color={T.ink} /></button>
              <div className="disp" style={{ fontSize: 17, color: T.ink }}>Voltar ao app</div>
            </div>
            <div className="scroll" style={{ flex: 1, overflowY: "auto", display: "flex", flexDirection: "column", minHeight: 0 }}>
              {session
                ? <EntregarView onSair={() => supabase.auth.signOut()} onToast={showToast} />
                : <LoginView onEntrar={async (email, senha) => { const { error } = await supabase.auth.signInWithPassword({ email, password: senha }); return !error; }} />}
            </div>
          </div>
        )}
      </div>

      {rascunho && <RevisaoModal rascunho={rascunho} setRascunho={setRascunho} onCancelar={() => setRascunho(null)} onConfirmar={confirmarEnvio} />}
      {sucesso && <SucessoModal onFechar={() => { setSucesso(null); setTab("mural"); }} />}
      <Toast msg={toast} />
    </div>
  );
}

// ============================ CONVERSAR ============================
function ConversarView({ msgs, iniciou, pensando, extraindo, input, setInput, scrollRef, onEnviar, onSend, onQuick, onProposta, participantes }) {
  const userTurns = msgs.filter((m) => m.role === "user").length;
  const pct = extraindo ? 100 : Math.min(90, userTurns * 30);
  const rapidas = ["É isso! 🔥", "Quero mudar", "Não sei ainda", "Explica melhor"];
  return (
    <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
      <div ref={scrollRef} className="scroll" style={{ flex: 1, overflowY: "auto", padding: 16, minHeight: 240 }}>
        {!iniciou && (
          <div className="rise" style={{ marginBottom: 16 }}>
            <div style={{ position: "relative", overflow: "hidden", borderRadius: 22, padding: "22px 20px 20px", background: T.gradHero, color: "#fff", boxShadow: T.shadowSoft }}>
              <div style={{ position: "absolute", top: -40, right: -30, width: 160, height: 160, background: "radial-gradient(circle,rgba(255,255,255,.28),transparent 70%)", pointerEvents: "none" }} />
              {participantes > 0 && <div className="eyebrow" style={{ display: "inline-block", background: "rgba(0,0,0,.18)", padding: "4px 10px", borderRadius: 999, marginBottom: 10 }}>🔥 já somos {participantes} {participantes === 1 ? "jovem" : "jovens"}</div>}
              <div className="disp" style={{ fontSize: 30, lineHeight: 1.05 }}>Sua ideia<br />aquece a política</div>
              <p style={{ fontSize: 13.5, marginTop: 8, marginBottom: 0, opacity: 0.95, lineHeight: 1.5 }}>Fale com o Sol. Ele vira o que você sente numa proposta — que chega direto nos candidatos.</p>
            </div>
            <div className="eyebrow" style={{ color: T.inkSoft, margin: "18px 0 8px" }}>Começa por um tema</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>
              {["Educação", "Trabalho e Renda", "Cultura e Esporte", "Saúde e Saúde Mental", "Mobilidade e Cidade"].map((t) => <ThemeChip key={t} tema={t} small onClick={() => onQuick(t)} />)}
            </div>
            <div style={{ height: 14 }} />
          </div>
        )}
        {msgs.map((m, i) => <Bubble key={i} role={m.role}>{m.content}</Bubble>)}
        {pensando && <Bubble role="assistant"><span style={{ opacity: 0.55 }}>digitando…</span></Bubble>}
      </div>

      <div style={{ borderTop: `1px solid ${T.line}`, background: T.paper, padding: 12 }}>
        {iniciou && (
          <>
            <div style={{ marginBottom: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, fontWeight: 700, color: T.inkSoft, marginBottom: 4 }}>
                <span>Sua ideia está {pct}% pronta</span>{pct >= 90 && <span style={{ color: T.orange }}>bora enviar! 🔥</span>}
              </div>
              <div style={{ height: 6, background: T.line, borderRadius: 999, overflow: "hidden" }}><div style={{ width: pct + "%", height: "100%", background: T.gradCta, borderRadius: 999, transition: "width .4s" }} /></div>
            </div>
            {!pensando && <div className="scroll" style={{ display: "flex", gap: 6, overflowX: "auto", marginBottom: 9 }}>
              {rapidas.map((r) => <button key={r} onClick={() => onSend(r)} style={{ flexShrink: 0, border: `1.5px solid ${T.line}`, background: T.paper2, color: T.inkSoft, borderRadius: 999, padding: "6px 12px", fontSize: 13, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap" }}>{r}</button>)}
            </div>}
            <button onClick={onProposta} disabled={extraindo} style={{ width: "100%", marginBottom: 10, padding: 13, borderRadius: 16, border: "none", background: T.gradCta, color: T.ink, fontFamily: "'Bricolage Grotesque',sans-serif", fontWeight: 700, fontSize: 15, cursor: "pointer", boxShadow: T.shadowSoft }}>
              {extraindo ? "Organizando sua proposta…" : "Enviar minha proposta 🔥"}
            </button>
          </>
        )}
        <div style={{ display: "flex", gap: 8 }}>
          <input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && onEnviar()} placeholder="Escreve aqui…" style={{ flex: 1, padding: "12px 14px", borderRadius: 14, border: `1.5px solid ${T.line}`, fontSize: 15, background: T.paper2, color: T.ink, fontFamily: "inherit" }} />
          <button onClick={onEnviar} disabled={pensando} aria-label="Enviar" style={{ width: 48, borderRadius: 14, border: "none", background: T.orange, color: "#fff", fontSize: 18, cursor: "pointer" }}>➤</button>
        </div>
      </div>
    </div>
  );
}

// ============================ MURAL ============================
function MuralView({ ideias, carregando, onCurtir, onToast }) {
  const [filtro, setFiltro] = useState(null);
  const [cidadeF, setCidadeF] = useState("");
  const [ranEver, setRanEver] = useState(false);
  useEffect(() => { setRanEver(true); }, []);
  const n = ideias.length;
  const temp = 34 + n * 0.3;
  const cidadesUnicas = Array.from(new Set(ideias.map((i) => (i.cidade || "").trim()).filter(Boolean))).sort();
  const temasComIdeias = TEMAS.filter((t) => ideias.some((i) => i.tema === t));
  let lista = filtro ? ideias.filter((i) => i.tema === filtro) : ideias;
  if (cidadeF) lista = lista.filter((i) => (i.cidade || "").trim() === cidadeF);

  return (
    <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
      <div style={{ padding: "18px 16px 6px", textAlign: "center" }}>
        <div className="eyebrow" style={{ color: T.inkSoft, marginBottom: 6 }}>Termômetro da juventude</div>
        <Gauge temp={temp} run={!ranEver} />
        <div style={{ display: "flex", justifyContent: "center", gap: 26, marginTop: 8 }}>
          {[[n, n === 1 ? "ideia" : "ideias"], [temasComIdeias.length, "temas"], [cidadesUnicas.length, cidadesUnicas.length === 1 ? "cidade" : "cidades"]].map(([v, l], i) => (
            <div key={i}><div className="disp tnum" style={{ fontSize: 20, color: T.ink }}>{v}</div><div style={{ fontSize: 11, color: T.inkMute, fontWeight: 600 }}>{l}</div></div>
          ))}
        </div>
      </div>

      {temasComIdeias.length > 0 && <div className="scroll" style={{ display: "flex", gap: 7, overflowX: "auto", padding: "10px 16px 6px" }}>
        <FilterPill label="Todas" active={!filtro} onClick={() => setFiltro(null)} />
        {temasComIdeias.map((t) => <ThemeChip key={t} tema={t} active={filtro === t} small onClick={() => setFiltro(filtro === t ? null : t)} />)}
      </div>}
      {cidadesUnicas.length > 0 && <div style={{ padding: "2px 16px 10px" }}>
        <select value={cidadeF} onChange={(e) => setCidadeF(e.target.value)} style={{ width: "100%", padding: "9px 12px", borderRadius: 12, border: `1.5px solid ${T.line}`, background: T.paper2, color: T.ink, fontSize: 14, fontFamily: "inherit" }}>
          <option value="">Todas as cidades</option>{cidadesUnicas.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>}

      <div className="scroll" style={{ overflowY: "auto", flex: 1, padding: "0 16px 18px" }}>
        {carregando && <p style={{ textAlign: "center", color: T.inkMute, marginTop: 30 }}>Carregando o mural…</p>}
        {!carregando && lista.length === 0 && <div style={{ textAlign: "center", marginTop: 44, color: T.inkSoft }}>
          <SunMark size={46} /><p className="disp" style={{ fontSize: 18, marginTop: 10, marginBottom: 2 }}>Seja a primeira brasa</p><p style={{ fontSize: 13 }}>Vai em Conversar e solta a primeira ideia da sua cidade.</p>
        </div>}
        {lista.map((idea) => <IdeiaCard key={idea.id} idea={idea} onCurtir={onCurtir} onToast={onToast} />)}
      </div>
    </div>
  );
}
function IdeiaCard({ idea, onCurtir, onToast }) {
  const cor = TEMA_COR[idea.tema] || T.orange;
  const [curtido, setCurtido] = useState(() => { try { return localStorage.getItem("curtiu:" + idea.id) === "1"; } catch { return false; } });
  const [n, setN] = useState(idea.curtidas || 0);
  const curtir = () => { if (curtido) return; setCurtido(true); setN(n + 1); try { localStorage.setItem("curtiu:" + idea.id, "1"); } catch (e) {} onCurtir(idea.id); onToast && onToast("Apoiou! 🔥"); };
  return (
    <div className="rise" style={{ background: T.paper2, border: `1px solid ${T.line}`, borderLeft: `5px solid ${cor}`, borderRadius: 14, padding: "13px 15px", marginBottom: 10, boxShadow: T.shadowSoft }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
        <span className="eyebrow" style={{ color: cor }}>{idea.tema}</span>
        <button onClick={curtir} style={{ display: "flex", alignItems: "center", gap: 5, border: `1.5px solid ${curtido ? cor : T.line}`, background: curtido ? tint(cor, "1A") : "transparent", color: curtido ? cor : T.inkSoft, borderRadius: 999, padding: "3px 10px", fontSize: 12.5, fontWeight: 700, cursor: curtido ? "default" : "pointer" }}>🔥 {n}</button>
      </div>
      <div className="disp" style={{ fontSize: 17, color: T.ink, lineHeight: 1.15, margin: "5px 0 7px" }}>{idea.titulo || "Proposta"}</div>
      {idea.problema && <p style={{ fontSize: 13.5, margin: "0 0 4px", color: T.inkSoft }}><b style={{ color: T.ink }}>Problema.</b> {idea.problema}</p>}
      {idea.proposta && <p style={{ fontSize: 13.5, margin: 0, color: T.inkSoft }}><b style={{ color: T.ink }}>Proposta.</b> {idea.proposta}</p>}
      {idea.cidade && <div style={{ display: "flex", alignItems: "center", gap: 4, marginTop: 9, fontSize: 12, color: T.inkMute, fontWeight: 600 }}><Icon name="pin" size={13} color={T.inkMute} />{idea.cidade}</div>}
    </div>
  );
}

// ============================ LOGIN ============================
function LoginView({ onEntrar }) {
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");
  const [loading, setLoading] = useState(false);
  const inp = { marginTop: 10, width: "100%", maxWidth: 300, padding: "12px 14px", borderRadius: 14, border: `1.5px solid ${T.line}`, fontSize: 15, background: T.paper2, color: T.ink, textAlign: "center", fontFamily: "inherit" };
  const tentar = async () => { if (!email || !senha) return; setLoading(true); const ok = await onEntrar(email.trim(), senha); setLoading(false); if (!ok) { setErro("E-mail ou senha incorretos."); setSenha(""); } };
  return (
    <div className="rise" style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 24 }}>
      <div style={{ width: 72, height: 72, borderRadius: 999, background: T.gradCta, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: T.shadowSoft }}><Icon name="lock" size={30} color="#fff" /></div>
      <div className="disp" style={{ fontSize: 24, color: T.ink, marginTop: 14 }}>Área da coordenação</div>
      <p style={{ fontSize: 13.5, color: T.inkSoft, marginTop: 6, maxWidth: 300, lineHeight: 1.5 }}>O dossiê é privado. Só a coordenação da JSB acessa e entrega aos candidatos.</p>
      <input type="email" value={email} onChange={(e) => { setEmail(e.target.value); setErro(""); }} placeholder="E-mail" style={inp} />
      <input type="password" value={senha} onChange={(e) => { setSenha(e.target.value); setErro(""); }} onKeyDown={(e) => e.key === "Enter" && tentar()} placeholder="Senha" style={inp} />
      {erro && <div style={{ color: T.red, fontSize: 13, marginTop: 8, fontWeight: 700 }}>{erro}</div>}
      <button onClick={tentar} disabled={loading} className="disp" style={{ marginTop: 14, width: "100%", maxWidth: 300, padding: 13, borderRadius: 16, border: "none", background: T.gradCta, color: T.ink, fontSize: 17, cursor: "pointer", boxShadow: T.shadowSoft }}>{loading ? "Entrando…" : "Entrar"}</button>
    </div>
  );
}

// ============================ ENTREGAR ============================
function EntregarView({ onSair, onToast }) {
  const [ideias, setIdeias] = useState([]);
  const [pendentes, setPendentes] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const carregar = async () => { const [d, p] = await Promise.all([listDossie(), listPendentes()]); setIdeias(d); setPendentes(p); setCarregando(false); };
  useEffect(() => { carregar(); }, []);
  const aprovar = async (id) => { await aprovarIdeia(id); onToast && onToast("Aprovada ✓"); carregar(); };
  const recusar = async (id) => { await recusarIdeia(id); onToast && onToast("Recusada"); carregar(); };
  const porTema = TEMAS.map((t) => ({ tema: t, itens: ideias.filter((i) => i.tema === t) })).filter((g) => g.itens.length).sort((a, b) => b.itens.length - a.itens.length);
  const cidades = new Set(ideias.map((i) => (i.cidade || "").trim().toLowerCase()).filter(Boolean)).size;
  const maxTema = porTema.length ? porTema[0].itens.length : 1;
  const copiar = async () => { try { await navigator.clipboard.writeText(montarRelatorio(ideias)); onToast && onToast("Relatório copiado ✓"); } catch (e) {} };

  const baixarPDF = () => {
    const w = window.open("", "_blank"); if (!w) return;
    const dataHoje = new Date().toLocaleDateString("pt-BR");
    const barras = porTema.map((g) => `<div class="brow"><div class="blab"><span>${g.tema}</span><b>${g.itens.length}</b></div><div class="btrack"><div class="bfill" style="width:${Math.round(g.itens.length / maxTema * 100)}%;background:${TEMA_COR[g.tema]}"></div></div></div>`).join("");
    const secoes = porTema.map((g) => {
      const cards = [...g.itens].sort((a, b) => (b.curtidas || 0) - (a.curtidas || 0)).map((i) => {
        const autor = esc([i.nome, i.cidade, i.idade].filter(Boolean).join(" · "));
        const lk = (i.curtidas || 0) >= 15 ? `<span class="hot">\ud83d\udd25 ${i.curtidas}</span>` : `<span class="lk">\ud83d\udd25 ${i.curtidas || 0}</span>`;
        return `<div class="card" style="border-left-color:${TEMA_COR[g.tema]}"><div class="ctop"><span class="ttag" style="color:${TEMA_COR[g.tema]}">${g.tema}</span>${lk}</div><div class="ctitle">${esc(i.titulo)}</div>${i.problema ? `<div class="cline"><b>Problema.</b> ${esc(i.problema)}</div>` : ""}${i.proposta ? `<div class="cline"><b>Proposta.</b> ${esc(i.proposta)}</div>` : ""}${autor ? `<div class="cauthor">${autor}</div>` : ""}</div>`;
      }).join("");
      return `<div class="sec"><div class="sechead"><span class="dot" style="background:${TEMA_COR[g.tema]}"></span><h2 style="color:${TEMA_COR[g.tema]}">${g.tema}</h2><span class="badge" style="background:${TEMA_COR[g.tema]}">${g.itens.length}</span></div>${cards}</div>`;
    }).join("");
    w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Dossiê Juventude 40 Graus</title>
    <link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,700;12..96,800&family=Archivo:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>*{box-sizing:border-box}body{margin:0;font-family:'Archivo',Arial,sans-serif;color:#2A1A10;background:#FCF4E6}.disp{font-family:'Bricolage Grotesque','Archivo',sans-serif;font-weight:800;letter-spacing:-.01em}.page{page-break-after:always}.page:last-child{page-break-after:auto}.cover{height:297mm;background:linear-gradient(150deg,#F5A623,#EF5B25 52%,#C4341A);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;position:relative;overflow:hidden}.cover .ray{position:absolute;top:-120px;right:-80px;width:420px;height:420px;background:radial-gradient(circle,rgba(255,255,255,.28),transparent 70%)}.cover img{width:70%;max-width:340px;border-radius:12px;box-shadow:0 20px 50px -20px rgba(0,0,0,.5)}.cover h1{font-size:42px;margin:24px 0 6px}.cover .sub{font-size:16px;opacity:.95}.cover .eb{font-size:12px;font-weight:700;letter-spacing:.2em;text-transform:uppercase;opacity:.9;margin-bottom:16px}.cover .foot{position:absolute;bottom:26px;font-size:12px;opacity:.9}.body{padding:24mm 18mm}.stats{display:flex;gap:12px;margin-bottom:22px}.stat{flex:1;background:#FFFBF2;border:1.5px solid #EADFC9;border-radius:14px;padding:13px;text-align:center}.stat b{font-size:26px;color:#EF5B25;display:block;font-family:'Bricolage Grotesque',sans-serif}.stat span{font-size:12px;color:#6E5A4C;font-weight:600}.eb2{font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#6E5A4C;margin:6px 0 10px}.chart{margin-bottom:24px}.brow{margin-bottom:9px}.blab{display:flex;justify-content:space-between;font-size:13px;margin-bottom:3px}.btrack{height:9px;background:#EADFC9;border-radius:999px;overflow:hidden}.bfill{height:100%;border-radius:999px}.sec{margin-bottom:18px;page-break-inside:avoid}.sechead{display:flex;align-items:center;gap:8px;margin:0 0 10px}.sechead h2{font-size:19px;margin:0;font-family:'Bricolage Grotesque',sans-serif}.dot{width:11px;height:11px;border-radius:999px}.badge{color:#fff;font-size:12px;font-weight:700;border-radius:999px;padding:2px 10px;font-family:'Bricolage Grotesque',sans-serif}.card{background:#FFFBF2;border:1px solid #EADFC9;border-left:5px solid;border-radius:12px;padding:12px 14px;margin-bottom:10px;page-break-inside:avoid}.ctop{display:flex;justify-content:space-between;align-items:center}.ttag{font-size:10.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.hot{font-size:12px;font-weight:700;color:#C4341A;background:#F5A62322;border-radius:999px;padding:2px 9px}.lk{font-size:12px;font-weight:600;color:#A2907E}.ctitle{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;font-size:17px;margin:4px 0 6px}.cline{font-size:13px;color:#6E5A4C;margin-bottom:3px}.cline b{color:#2A1A10}.cauthor{font-size:11px;color:#A2907E;font-weight:600;margin-top:6px}.foot2{border-top:1px solid #EADFC9;margin-top:20px;padding-top:12px;font-size:11px;color:#A2907E;display:flex;justify-content:space-between}@media print{.noprint{display:none}}</style></head><body>
    <div class="page"><div class="cover"><div class="ray"></div><div class="eb">Políticas Públicas de Juventude</div><img src="${LOGO_BANNER}"/><h1 class="disp">Dossiê da Juventude</h1><div class="sub">JSB Ceará · ciclo 2026</div><div class="foot">Gerado em ${dataHoje} · juventude-40-graus.vercel.app</div></div></div>
    <div class="page"><div class="body"><div class="stats"><div class="stat"><b>${ideias.length}</b><span>propostas</span></div><div class="stat"><b>${porTema.length}</b><span>temas</span></div><div class="stat"><b>${cidades}</b><span>cidades</span></div></div><div class="chart"><div class="eb2">Temas mais pedidos pela juventude</div>${barras}</div><div class="eb2">Propostas por tema</div>${secoes}<div class="foot2"><span>Juventude 40 Graus · JSB Ceará</span><span>Gerado em ${dataHoje}</span></div><button class="noprint" onclick="window.print()" style="margin-top:18px;padding:12px 22px;background:#F5A623;border:none;border-radius:12px;font-weight:bold;cursor:pointer">Salvar como PDF / Imprimir</button></div></div>
    </body></html>`);
    w.document.close();
  };

  return (
    <div className="scroll rise" style={{ overflowY: "auto", flex: 1, padding: 16 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <div className="disp" style={{ fontSize: 23, color: T.ink }}>Coordenação</div>
        <button onClick={onSair} style={{ fontSize: 12, fontWeight: 700, padding: "5px 12px", borderRadius: 999, border: `1.5px solid ${T.line}`, background: "transparent", color: T.inkSoft, cursor: "pointer" }}>Sair</button>
      </div>

      {pendentes.length > 0 && (
        <div style={{ marginTop: 14, background: tint(T.gold, "1A"), border: `1.5px solid ${tint(T.gold, "66")}`, borderRadius: 16, padding: 12 }}>
          <div className="eyebrow" style={{ color: T.orangeDeep, marginBottom: 8 }}>Aguardando aprovação ({pendentes.length})</div>
          {pendentes.map((i) => (
            <div key={i.id} style={{ background: T.paper2, border: `1px solid ${T.line}`, borderRadius: 12, padding: "11px 13px", marginBottom: 9 }}>
              <div className="eyebrow" style={{ color: TEMA_COR[i.tema] || T.orange }}>{i.tema}</div>
              <div className="disp" style={{ fontSize: 16, margin: "3px 0 5px", color: T.ink }}>{i.titulo || "Proposta"}</div>
              {i.problema && <p style={{ fontSize: 12.5, margin: "0 0 3px", color: T.inkSoft }}><b style={{ color: T.ink }}>Problema.</b> {i.problema}</p>}
              {i.proposta && <p style={{ fontSize: 12.5, margin: 0, color: T.inkSoft }}><b style={{ color: T.ink }}>Proposta.</b> {i.proposta}</p>}
              <div style={{ fontSize: 11, color: T.inkMute, marginTop: 6 }}>{[i.nome, i.cidade, i.idade].filter(Boolean).join(" · ") || "Anônimo"}</div>
              <div style={{ display: "flex", gap: 8, marginTop: 9 }}>
                <button onClick={() => aprovar(i.id)} style={{ flex: 1, padding: 9, borderRadius: 10, border: "none", background: "#1E9E6A", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>Aprovar</button>
                <button onClick={() => recusar(i.id)} style={{ flex: 1, padding: 9, borderRadius: 10, border: `1.5px solid ${T.line}`, background: "transparent", color: T.red, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>Recusar</button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="disp" style={{ fontSize: 18, color: T.ink, margin: "18px 0 2px" }}>Dossiê da juventude</div>
      <div style={{ display: "flex", gap: 8, margin: "10px 0 14px" }}>
        {[[ideias.length, "propostas"], [porTema.length, "temas"], [cidades, "cidades"]].map(([v, l], i) => (
          <div key={i} style={{ flex: 1, background: T.paper2, border: `1px solid ${T.line}`, borderRadius: 12, padding: "10px 6px", textAlign: "center" }}><div className="disp tnum" style={{ fontSize: 22, color: T.orange }}>{v}</div><div style={{ fontSize: 11, color: T.inkSoft, fontWeight: 600 }}>{l}</div></div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
        <button onClick={copiar} disabled={!ideias.length} style={{ flex: 1, padding: 12, borderRadius: 14, border: `1.5px solid ${T.line}`, background: T.paper2, color: T.ink, fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Copiar texto</button>
        <button onClick={baixarPDF} disabled={!ideias.length} className="disp" style={{ flex: 1, padding: 12, borderRadius: 14, border: "none", background: T.gradCta, color: T.ink, fontSize: 14, cursor: "pointer", boxShadow: T.shadowSoft }}>Baixar PDF</button>
      </div>
      {carregando && <p style={{ color: T.inkMute }}>Carregando…</p>}
      {!carregando && porTema.length === 0 && <p style={{ color: T.inkSoft }}>Nenhuma proposta aprovada ainda.</p>}
      {porTema.length > 0 && <div style={{ marginBottom: 18 }}>
        <div className="eyebrow" style={{ color: T.inkSoft, marginBottom: 8 }}>Temas mais pedidos</div>
        {porTema.map((g) => <div key={g.tema} style={{ marginBottom: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3, color: T.ink }}><span>{g.tema}</span><b className="tnum">{g.itens.length}</b></div>
          <div style={{ height: 8, background: T.line, borderRadius: 999, overflow: "hidden" }}><div style={{ width: (g.itens.length / maxTema * 100) + "%", height: "100%", background: TEMA_COR[g.tema], borderRadius: 999, transition: "width .5s" }} /></div>
        </div>)}
      </div>}
      {porTema.map((g) => <div key={g.tema} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}><span className="disp" style={{ fontSize: 16, color: TEMA_COR[g.tema] }}>{g.tema}</span><span className="tnum" style={{ fontSize: 11, fontWeight: 700, background: TEMA_COR[g.tema], color: "#fff", borderRadius: 999, padding: "1px 9px" }}>{g.itens.length}</span></div>
        {g.itens.map((i) => <div key={i.id} style={{ fontSize: 13.5, borderLeft: `3px solid ${T.line}`, paddingLeft: 10, marginBottom: 8, color: T.inkSoft }}><b style={{ color: T.ink }}>{i.titulo}</b>{i.proposta ? ` — ${i.proposta}` : ""}{(i.nome || i.cidade) && <span style={{ display: "block", fontSize: 11, color: T.inkMute, marginTop: 2 }}>{[i.nome, i.cidade, i.idade].filter(Boolean).join(" · ")}</span>}</div>)}
      </div>)}
    </div>
  );
}

function montarRelatorio(ideias) {
  const L = ["JUVENTUDE 40 GRAUS — DOSSIÊ DE POLÍTICAS PÚBLICAS DE JUVENTUDE", "JSB Ceará · ciclo 2026", `Total: ${ideias.length}`, "=".repeat(52)];
  TEMAS.forEach((t) => { const it = ideias.filter((i) => i.tema === t); if (!it.length) return; L.push("", `## ${t.toUpperCase()} (${it.length})`); it.forEach((i, x) => { L.push("", `${x + 1}. ${i.titulo || ""}`); if (i.problema) L.push(`   Problema: ${i.problema}`); if (i.proposta) L.push(`   Proposta: ${i.proposta}`); const a = [i.nome, i.cidade, i.idade].filter(Boolean).join(", "); if (a) L.push(`   Por: ${a}`); }); });
  return L.join("\n");
}
function esc(s) { return String(s || "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

