function RevisaoModal({ rascunho, setRascunho, onCancelar, onConfirmar }) {
  const set = (k, v) => setRascunho((r) => ({ ...r, [k]: v }));
  const inp = { width: "100%", padding: "9px 11px", borderRadius: 10, border: `1.5px solid ${T.line}`, fontSize: 14, marginTop: 3, background: T.paper2, color: T.ink, fontFamily: "inherit" };
  const lab = { fontSize: 11, fontWeight: 700, color: T.inkSoft, textTransform: "uppercase", letterSpacing: ".1em" };
  const Cont = ({ v }) => <div style={{ fontSize: 11, color: T.inkMute, marginTop: 3, display: "flex", justifyContent: "space-between" }}><span>Dica: seja concreto e diga onde.</span><span className="tnum">{(v || "").length}/400</span></div>;
  return (
    <Overlay>
      <div className="disp" style={{ fontSize: 22, color: T.ink }}>Revise sua proposta</div>
      <p style={{ fontSize: 12.5, marginTop: 2, marginBottom: 12, color: T.inkSoft }}>Passa por uma revisão rápida e depois entra no mural (sem seu nome, só a cidade).</p>
      <label style={lab}>Título</label>
      <input style={inp} value={rascunho.titulo} onChange={(e) => set("titulo", e.target.value)} />
      <label style={{ ...lab, display: "block", marginTop: 12 }}>Tema</label>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 5 }}>{TEMAS.map((t) => <ThemeChip key={t} tema={t} active={rascunho.tema === t} small onClick={() => set("tema", t)} />)}</div>
      <label style={{ ...lab, display: "block", marginTop: 12 }}>Problema</label>
      <textarea style={{ ...inp, minHeight: 52 }} maxLength={400} value={rascunho.problema} onChange={(e) => set("problema", e.target.value)} /><Cont v={rascunho.problema} />
      <label style={{ ...lab, display: "block", marginTop: 10 }}>Proposta</label>
      <textarea style={{ ...inp, minHeight: 52 }} maxLength={400} value={rascunho.proposta} onChange={(e) => set("proposta", e.target.value)} /><Cont v={rascunho.proposta} />
      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        <div style={{ flex: 1 }}><label style={lab}>Nome (opcional)</label><input style={inp} value={rascunho.nome} onChange={(e) => set("nome", e.target.value)} /></div>
        <div style={{ flex: 1 }}><label style={lab}>Cidade</label><input style={inp} value={rascunho.cidade} onChange={(e) => set("cidade", e.target.value)} /></div>
        <div style={{ width: 116 }}><label style={lab}>Faixa etária</label>
          <select style={{ ...inp, padding: "10px 8px" }} value={rascunho.idade} onChange={(e) => set("idade", e.target.value)}>
            <option value="">—</option><option value="16–17">16–17</option><option value="18–24">18–24</option><option value="25–29">25–29</option><option value="30–35">30–35</option>
          </select>
        </div>
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 16 }}>
        <button onClick={onCancelar} style={{ flex: 1, padding: 12, borderRadius: 14, border: `1.5px solid ${T.line}`, background: "transparent", color: T.ink, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Voltar</button>
        <button onClick={onConfirmar} disabled={!rascunho.titulo && !rascunho.proposta} className="disp" style={{ flex: 2, padding: 12, borderRadius: 14, border: "none", background: T.gradCta, color: T.ink, fontSize: 16, cursor: "pointer", boxShadow: T.shadowSoft }}>Publicar no mural 🔥</button>
      </div>
    </Overlay>
  );
}
